import json,pathlib,hashlib,time,concurrent.futures,collections
root=pathlib.Path('/root/autodl-tmp/vsmt_outputs/lean-s1-02-window-probe-f2982a6')
def run(p):
 hashes={}
 def read(f):
  b=f.read_bytes();hashes[str(f.relative_to(p))]=hashlib.sha256(b).hexdigest();return json.loads(b)
 rec=read(p/'receipt.json') if (p/'receipt.json').exists() else {'status':'running'}
 s=read(p/'provenance/window_segment.json') if (p/'provenance/window_segment.json').exists() else None
 r={'house':p.name,'receipt':rec,'window_segment':s,'input_sha256':hashes}
 if not s:return r
 w=read(p/'provenance/window_verdicts.json') if (p/'provenance/window_verdicts.json').exists() else None
 if w:
  subs=w['subjects'];sealed={c for c,d in subs.items() if d['sealed']}
 else:
  oldbase=pathlib.Path('/root/autodl-tmp/vsmt_outputs')/('lean-s1-02a-7c10d2c' if p.name[-5:] in ['00460','01451','03394','08566'] else 'lean-s1-02b-7c10d2c')
  raw=(oldbase/p.name/'provenance/window_verdicts.json').read_bytes()
  hashes['old_window_verdicts_reference']=hashlib.sha256(raw).hexdigest()
  subs=json.loads(raw)['subjects'];sealed=None
  r['container_ids_source']='old same-house usable IDs; no new sealing computed'
 lo,hi=s['segment'];frames=[]
 for i in range(lo+1,hi+1):
  pr=read(p/'private'/f'{i:04d}.frame.json');pub=read(p/'public'/f'{i:04d}.frame.json')
  frames.append({'index':i,'action':pub['action_summary']['action'],'pixels':pr['object_visibility']})
 r['actions']=dict(collections.Counter(f['action'] for f in frames))
 r['rendered_usable_containers']=sum(any(f['pixels'].get(c,0)>0 for f in frames) for c in subs)
 r['usable_containers']=len(subs)
 obj=read(p/'provenance/object_table.json') if (p/'provenance/object_table.json').exists() else None
 r['prefix_diagnostics']={}
 for n in [10,20,30,40]:
  if hi-lo<n:continue
  rr={'renderer_zero_usable':[c for c in subs if all(f['pixels'].get(c,0)==0 for f in frames[:n])]}
  if w:
   visible={v['container'] for v in w['verdicts'] if lo<v['observation_index']<=lo+n and v['unoccluded']>0}
   u=sealed-visible;rr['stored_verdict_U']=sorted(u)
   if obj:rr['eligible_sources']=[o['object_id'] for o in obj['objects'] if o['eligible'] and o['parent_receptacle'] in u]
  r['prefix_diagnostics'][str(n)]=rr
 r['per_container']={c:{'max_rendered_pixels':max(f['pixels'].get(c,0) for f in frames),'frames_rendered':sum(f['pixels'].get(c,0)>0 for f in frames)} for c in subs}
 if w:
  r['recorded_U']=w['invisible']
  r['sealed_count']=len(sealed)
  if obj:r['eligible_source_count']=sum(o['eligible'] and o['parent_in_U'] for o in obj['objects'])
 return r
tasks=sorted(p for p in root.iterdir() if p.is_dir() and p.name.startswith('procthor'))
with concurrent.futures.ThreadPoolExecutor(max_workers=len(tasks)) as pool:rows=list(pool.map(run,tasks))
print(json.dumps({'schema':'vsmt-window-probe-readonly-audit-v1','snapshot_unix':time.time(),'root':str(root),'workers':len(tasks),'scope':'existing JSON only; prefix diagnostics are not reruns or usable samples','rows':rows},indent=1))
